package com.example.demo;

import java.util.Optional;

public interface TitleRepository {
    Optional<String> findTitle(long id);
}

package com.example.demo;

public class EntryService {
    private final TitleRepository repository;

    public EntryService(TitleRepository repository) {
        this.repository = repository;
    }

    public String title(long id) {
        return repository.findTitle(id)
                .orElseThrow(() -> new IllegalArgumentException("Entry missing"));
    }
}

package com.example.demo;

import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class EntryServiceTest {
    @Mock
    private TitleRepository repository;

    @InjectMocks
    private EntryService service;

    @Test
    void returnsStoredTitle() {
        when(repository.findTitle(7L)).thenReturn(Optional.of("First entry"));

        assertEquals("First entry", service.title(7L));
        verify(repository).findTitle(7L);
    }

    @Test
    void rejectsMissingEntry() {
        when(repository.findTitle(8L)).thenReturn(Optional.empty());

        assertThrows(IllegalArgumentException.class, () -> service.title(8L));
    }
}

package com.example.demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class DemoApplication {
    public static void main(String[] args) {
        SpringApplication.run(DemoApplication.class, args);
    }
}
